local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local K={204,184,182,126,220,38,47,96,77,189,210,8,233,203,219,85,19,217,1,101,248,22,190,46,200,78,115,252,193,241,19,134}
local P=""
local S0=110
local function bx(a,b)
 local r=0
 local m=1
 while a>0 or b>0 do
  local aa=a%2
  local bb=b%2
  if aa~=bb then r=r+m end
  a=math.floor(a/2)
  b=math.floor(b/2)
  m=m*2
 end
 return r
end
local function D(s)
 local o={}
 local n=0
 local bits=0
 for i=1,#s do
  local c=s:sub(i,i)
  if c~="=" then
   local v=B:find(c,1,true)
   if v then
    v=v-1
    n=n*64+v
    bits=bits+6
    if bits>=8 then
     bits=bits-8
     o[#o+1]=string.char(math.floor(n/2^bits)%256)
     n=n%2^bits
    end
   end
  end
 end
 return table.concat(o)
end
local C=D(P)
local O={}
local S=S0
for i=1,#C do
 local b=string.byte(C,i)
 local k=K[((i-1)%#K)+1]
 local v
 if bit32 and bit32.bxor then
  v=bit32.bxor(b,k,S)
 else
  v=bx(bx(b,k),S)
 end
 O[#O+1]=string.char(v)
 S=(S+v+k+((i-1)%256))%256
end
local F=table.concat(O)
local L=loadstring or load
assert(L,"loadstring is unavailable")
local f,e=L(F,"@LUNAR_Hub_LootToForge")
assert(f,e)
return f()
